mapper.select:
SELECT pt.point_transaction_id AS pointTransactionId, pt.point_wallet_id AS pointWalletId, pt.transaction_type AS transactionType, pt.point_amount AS pointAmount, pt.reason_type AS reasonType, DATE_FORMAT( pt.created_at, '%Y-%m-%d %H:%i:%s' ) AS createdAt FROM point_transaction_tbl pt INNER JOIN point_wallet_tbl pw ON pw.point_wallet_id = pt.point_wallet_id WHERE pw.user_id = #{userId}
AND pt.transaction_type = #{transactionType}
ORDER BY pt.created_at DESC, pt.point_transaction_id DESC

mapper.update:
UPDATE point_wallet_tbl
SET point_balance = point_balance + #{pointAmount}
WHERE point_wallet_id = #{pointWalletId}

UPDATE point_wallet_tbl
SET point_balance = point_balance - #{pointAmount}
WHERE user_id = #{userId}
